<template><section class="my-4 p-4 border rounded-lg" aria-label="我的观影记录"><h3 class="font-semibold mb-3">我的观影记录</h3><p v-if="!auth.isAuthenticated">登录后可收藏和记录看过的电影。</p><div v-else class="flex gap-3 flex-wrap"><button :disabled="busy" class="px-4 py-2 border rounded" :aria-pressed="state.favorite" @click="save({favorite:!state.favorite})">{{state.favorite?'★ 已收藏':'☆ 收藏'}}</button><button :disabled="busy" class="px-4 py-2 border rounded" :aria-pressed="state.seen" @click="save({seen:!state.seen})">{{state.seen?'✓ 已看过':'标记看过'}}</button><p role="status">{{message}}</p></div><p v-if="error" role="alert" class="text-red-600">{{error}}</p><p class="text-sm text-gray-500 mt-2">看过的电影将从登录后的对话推荐中排除。</p><div v-if="auth.isAuthenticated" class="mt-4"><h4 class="font-semibold">根据你的观影记录推荐</h4><ul><li v-for="movie in suggestions" :key="movie.movie_id"><a class="text-blue-700 underline" :href="'/movie/'+movie.movie_id">{{movie.title}}</a></li></ul><p v-if="recommendationError" role="status">{{recommendationError}}</p></div></section></template>
<script setup>
import {ref,watch} from 'vue'
import {useAuthStore} from '../stores/auth'
const props=defineProps({movieId:{type:Number,required:true},revision:{type:Number,default:0}}),auth=useAuthStore(),state=ref({favorite:false,seen:false}),busy=ref(false),message=ref(''),error=ref('')
const suggestions=ref([]),recommendationError=ref('')
let generation=0
async function refreshRecommendations(id){try{const r=await fetch('/api/me/recommendations?limit=4',{headers:{Authorization:'Bearer '+auth.token}});if(!r.ok)throw new Error();const data=await r.json();if(id===generation){suggestions.value=data.items;recommendationError.value=''}}catch{if(id===generation)recommendationError.value='推荐暂时不可用，请稍后重试。'}}
async function request(method,body){const r=await fetch('/api/me/movies/'+props.movieId+'/behavior',{method,headers:{'Content-Type':'application/json',Authorization:'Bearer '+auth.token},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'操作失败，请重试');return d}
watch(()=>[props.movieId,auth.isAuthenticated,props.revision],async()=>{const id=++generation;error.value='';message.value='';state.value={favorite:false,seen:false};suggestions.value=[];if(!auth.isAuthenticated)return;busy.value=true;try{const d=await request('GET');if(id===generation){state.value=d;await refreshRecommendations(id)}}catch(e){if(id===generation)error.value=e.message}finally{if(id===generation)busy.value=false}},{immediate:true})
async function save(change){if(busy.value)return;const id=generation;busy.value=true;error.value='';try{const d=await request('PUT',change);if(id===generation){state.value=d;message.value='已保存';await refreshRecommendations(id)}}catch(e){if(id===generation)error.value=e.message}finally{busy.value=false}}
</script>
